// The TypeScript half of make parity: every case generated by vt_measure must match (10.5).
import { readdirSync, readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import { derive, DeriveInput, Rules, SITES, SiteResult } from '../../src/measure/derive';

const DIR = resolve(import.meta.dirname, '../../../../packages/parity-fixtures/cases');
const FILES = readdirSync(DIR).filter((name) => name.endsWith('.json'));
const TOLERANCE_MM = 0.5;
const CLOSE = 1e-6;

interface Case {
  name: string;
  input: DeriveInput;
  rules: Rules;
  expected: {
    scale_front: number | null;
    scale_side: number | null;
    scale_stature: number | null;
    disagreement_pct: number | null;
    sites: Record<string, SiteResult>;
  };
}

function near(actual: number | null, wanted: number | null, within: number): void {
  if (wanted === null) expect(actual).toBeNull();
  else expect(Math.abs((actual as number) - wanted)).toBeLessThanOrEqual(within);
}

describe('parity with vt_measure', () => {
  it('has the cases', () => {
    expect(FILES.length).toBeGreaterThanOrEqual(40);
  });

  it.each(FILES)('%s', (file) => {
    const { input, rules, expected } = JSON.parse(readFileSync(resolve(DIR, file), 'utf8')) as Case;
    const result = derive(input, rules);
    near(result.scale_front, expected.scale_front, CLOSE);
    near(result.scale_side, expected.scale_side, CLOSE);
    near(result.scale_stature, expected.scale_stature, CLOSE);
    near(result.disagreement_pct, expected.disagreement_pct, CLOSE);
    for (const site of SITES) {
      const got = result.sites[site];
      const want = expected.sites[site];
      expect(got.flag, site).toBe(want.flag);
      expect(got.reasons, site).toEqual(want.reasons);
      expect(got.value_mm, site).toBe(want.value_mm);
      near(got.raw_mm, want.raw_mm, TOLERANCE_MM);
      near(got.level_fraction, want.level_fraction, CLOSE);
      near(got.a_mm, want.a_mm, CLOSE);
      near(got.b_mm, want.b_mm, CLOSE);
      near(got.perimeter_mm, want.perimeter_mm, CLOSE);
      near(got.correction_factor, want.correction_factor, CLOSE);
    }
  });
});
